ee:message.ee:set-payload:
%dw 2.0
import * from dw::core::Binaries
output multipart/form-data
---
{
    parts : {
        callback : {
            headers : { "Content-Type" : "text/plain" },
            content : '{"noAuthUrl": "callBackURL"}'
        },
        file : {
            headers : {
                "Content-Disposition" : {
                    "name": "file",
                    "filename": vars.fileMetaData.fileName,
                    "subtype": "form-data"
                },
                "Content-Type" : vars.fileMetaData.mimeType
            },
            content : fromBase64(vars.fileBase64)
        }
    }
}

ee:variables.ee:set-variable:
%dw 2.0
output application/java
var dlName = upper(trim(vars.dlData.fullName default ""))
var passportName = upper(trim(vars.passportData.fullName default ""))
var formName = upper(trim(vars.loanData.name default ""))
var nameMatch = dlName == passportName and dlName == formName

var dlDob = vars.dlData.dob default ""
var passportDob = vars.passportData.dob default ""
var formDob = vars.loanData.dob default ""
var dobMatch = dlDob == passportDob and dlDob == formDob

var declaredIdType = upper(trim(vars.loanData.idType default ""))
var declaredIdNumber = trim(vars.loanData.idNumber default "")
var idNumMatch =
    if (declaredIdType == "DRIVING LICENSE" or declaredIdType == "DL")
        declaredIdNumber == trim(vars.dlData.licenseNumber default "")
    else if (declaredIdType == "PASSPORT")
        declaredIdNumber == trim(vars.passportData.passportNumber default "")
    else
        false

var allMatch = nameMatch and dobMatch and idNumMatch
---
{
    status: if (allMatch) "New" else "Needs Verification",
    notes: if (allMatch) null else (
        (if (not nameMatch) "Name mismatch across documents. " else "") ++
        (if (not dobMatch) "DOB mismatch across documents. " else "") ++
        (if (not idNumMatch) "Declared ID number (" ++ declaredIdType ++ ") does not match the corresponding document. " else "")
    )
}

salesforce:create.salesforce:records:
#[vars.documentAttachments map ((doc) -> {
                        Title: doc.fileName,
                        PathOnClient: doc.fileName,
                        VersionData: doc.base64Content,
                        FirstPublishLocationId: vars.loanApplication.items[0].id
                    })]

set-variable.value:
#[%dw 2.0
output application/java
var rawId =
    if (vars.currentDocType == "DRIVING_LICENSE") (vars.dlData.licenseNumber default "")
    else if (vars.currentDocType == "PASSPORT") (vars.passportData.passportNumber default "")
    else if (vars.currentDocType == "LOAN_APPLICATION_FORM") (vars.loanData.idNumber default "")
    else ""
var keepLength = 4
var maskLength = sizeOf(rawId) - keepLength
---
if (maskLength > 0) rawId[0 to (maskLength - 1)] else ""]

ee:message.ee:set-payload:
%dw 2.0
import * from dw::core::Binaries
output multipart/form-data
var idMask = vars.idNumberToMask default ""
var baseActions = [{ 'type': "ocr", language: "english" }]
var redactActions = if (idMask != "") [
    {
        'type': "createRedactions",
        strategy: "text",
        strategyOptions: {
            text: idMask,
            includeAnnotations: true,
            caseSensitive: false
        }
    },
    { 'type': "applyRedactions" }
] else []
---
{
    parts: {
        instructions: {
            headers: { "Content-Type": "application/json" },
            content: {
                parts: [ { file: "document" } ],
                actions: baseActions ++ redactActions
            }
        },
        document: {
            headers: {
                "Content-Disposition": { name: "document", filename: vars.fileMetaData.fileName },
                "Content-Type": vars.fileMetaData.mimeType
            },
            content: fromBase64(vars.fileBase64)
        }
    }
}
